css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; border-radius: 22%; box-shadow: inset 0 0 0 calc(var(--loader-size) * .07) var(--accent-2); animation: box-fill calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
.loader span { position: absolute; left: 50%; top: 44%; border: calc(var(--loader-size) * .085) solid #f8fafc; border-top: 0; border-left: 0; transform: translate(-58%, -64%) rotate(45deg); animation: tick calc(var(--loader-speed) * 2.2) ease-out infinite; }
@keyframes box-fill { 0%, 16% { background: transparent; } 32%, 74% { background: var(--accent); } 92%, 100% { background: transparent; } }
@keyframes tick { 0%, 24% { opacity: 0; width: 0; height: 0; } 32% { opacity: 1; width: 0; height: 30%; } 46% { width: 30%; height: 30%; } 74% { opacity: 1; width: 30%; height: 30%; } 84%, 100% { opacity: 0; width: 0; height: 0; } }
